import { setTimeout as sleep } from 'node:timers/promises';
import type { DatabaseSync } from 'node:sqlite';
import { openDatabase, immediateTransaction } from './db.ts';

const STEP_MS = 100;
const POLL_MS = 200;
const HEARTBEAT_MS = 1_000;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;
const TRANSIENT_ERROR = 'transient failure';

interface ClaimedJob {
  id: string;
  input: string;
  steps: number;
  failAttempts: number;
  /** The number of this attempt, counting from 1. */
  attempt: number;
}

const db = openDatabase();
let stopping = false;

function nowIso(): string {
  return new Date().toISOString();
}

function heartbeat(database: DatabaseSync): void {
  database
    .prepare(
      'INSERT INTO worker_heartbeat (id, last_seen_ms) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET last_seen_ms = excluded.last_seen_ms',
    )
    .run(Date.now());
}

/**
 * Jobs left `running` by a worker that died are queued again. Their interrupted attempt stays
 * counted in `attempts`, because it was started.
 */
function recoverInterruptedJobs(database: DatabaseSync): number {
  return immediateTransaction(database, () => {
    const result = database
      .prepare(
        `UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = 0, updated_at = ?
         WHERE status = 'running'`,
      )
      .run(nowIso());
    return Number(result.changes);
  });
}

/** Atomically takes the oldest queued job that is due, marking it running for a new attempt. */
function claimNext(database: DatabaseSync): ClaimedJob | undefined {
  return immediateTransaction(database, () => {
    const row = database
      .prepare(
        `SELECT id, input, steps, fail_attempts, attempts FROM jobs
         WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1`,
      )
      .get(Date.now()) as
      | { id: string; input: string; steps: number; fail_attempts: number; attempts: number }
      | undefined;
    if (!row) return undefined;
    database
      .prepare(`UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE id = ?`)
      .run(nowIso(), row.id);
    return {
      id: row.id,
      input: row.input,
      steps: row.steps,
      failAttempts: row.fail_attempts,
      attempt: row.attempts + 1,
    };
  });
}

function setProgress(database: DatabaseSync, id: string, completed: number): void {
  database
    .prepare(`UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'`)
    .run(completed, nowIso(), id);
}

function requeueForRetry(database: DatabaseSync, id: string): void {
  database
    .prepare(
      `UPDATE jobs SET status = 'queued', progress_completed = 0, error = NULL, available_at = ?, updated_at = ?
       WHERE id = ? AND status = 'running'`,
    )
    .run(Date.now() + RETRY_DELAY_MS, nowIso(), id);
}

function completeJob(database: DatabaseSync, id: string, steps: number, input: string): void {
  database
    .prepare(
      `UPDATE jobs SET status = 'completed', progress_completed = ?, result_output = ?, error = NULL, updated_at = ?
       WHERE id = ? AND status = 'running'`,
    )
    .run(steps, input.toUpperCase(), nowIso(), id);
}

function failJob(database: DatabaseSync, id: string): void {
  database
    .prepare(
      `UPDATE jobs SET status = 'failed', result_output = NULL, error = ?, updated_at = ?
       WHERE id = ? AND status = 'running'`,
    )
    .run(TRANSIENT_ERROR, nowIso(), id);
}

/** Runs one attempt. Returns early without changing state if the worker is stopping. */
async function runAttempt(database: DatabaseSync, job: ClaimedJob): Promise<void> {
  if (job.attempt <= job.failAttempts) {
    // Simulated transient failure: the first step fails before any progress is recorded.
    await sleep(STEP_MS);
    if (stopping) return requeueForRetry(database, job.id);
    if (job.attempt < MAX_ATTEMPTS) requeueForRetry(database, job.id);
    else failJob(database, job.id);
    return;
  }

  for (let completed = 1; completed <= job.steps; completed++) {
    await sleep(STEP_MS);
    if (stopping) return requeueForRetry(database, job.id);
    setProgress(database, job.id, completed);
  }
  completeJob(database, job.id, job.steps, job.input);
}

async function main(): Promise<void> {
  for (const signal of ['SIGINT', 'SIGTERM'] as const) {
    process.on(signal, () => {
      stopping = true;
    });
  }

  const recovered = recoverInterruptedJobs(db);
  heartbeat(db);
  const beat = setInterval(() => {
    try {
      heartbeat(db);
    } catch (e) {
      console.error('heartbeat failed:', e);
    }
  }, HEARTBEAT_MS);

  console.log(`worker started${recovered > 0 ? `, requeued ${recovered} interrupted job(s)` : ''}`);

  while (!stopping) {
    try {
      const job = claimNext(db);
      if (job) await runAttempt(db, job);
      else await sleep(POLL_MS);
    } catch (e) {
      console.error('worker iteration failed:', e);
      await sleep(POLL_MS);
    }
  }

  clearInterval(beat);
  try {
    db.prepare('DELETE FROM worker_heartbeat WHERE id = 1').run();
  } catch {
    // best effort: the server treats a stale heartbeat as down anyway
  }
  db.close();
  console.log('worker stopped');
}

await main();

